gate_initial.text:
func (gate Gate) AdmitInitial(ctx context.Context) (AcceptedInstall, error) {
	if err := gate.requireInitialJournalAbsent(); err != nil {
		return AcceptedInstall{}, err
	}
	if err := gate.prerequisites(); err != nil {
		return AcceptedInstall{}, err
	}
	now, err := gate.checkedNow()
	if err != nil {
		return AcceptedInstall{}, err
	}
	if _, err := gate.Markers.ReadIdentity(); err == nil || !errors.Is(err, os.ErrNotExist) {
		return AcceptedInstall{}, fmt.Errorf("%w: first install requires an absent marker: %v", ErrAdmission, err)
	}
	prior, priorErr := gate.Markers.ReadInitialFormation()
	if priorErr != nil && !errors.Is(priorErr, os.ErrNotExist) {
		return AcceptedInstall{}, fmt.Errorf("read current initial formation recovery state: %w", priorErr)
	}
	pending, pendingErr := gate.Markers.readInitialExport()
	if pendingErr != nil && !errors.Is(pendingErr, os.ErrNotExist) || pendingErr == nil && priorErr != nil {
		return AcceptedInstall{}, fmt.Errorf("%w: invalid initial export recovery state: %v", ErrAdmission, pendingErr)
	}
	anchorEnvelope, err := proofEnvelope(gate.AnchorWire)
	if err != nil {
		return AcceptedInstall{}, err
	}
	anchor, err := bootstrap.VerifyBootstrapAnchor(anchorEnvelope, gate.Roots, gate.Expected, now, bootstrap.BootstrapAnchorTrustPolicy())
	if err != nil {
		return AcceptedInstall{}, fmt.Errorf("verify current baked anchor: %w", err)
	}
	ctx, stop := context.WithDeadline(ctx, anchor.ExpiresAt())
	defer stop()
	scope, instanceID, err := gate.locate(ctx)
	if err != nil {
		return AcceptedInstall{}, err
	}
	state, ledger, err := gate.currentSlot(ctx, anchor, scope)
	if err != nil {
		return AcceptedInstall{}, err
	}
	observed, err := gate.observe(ctx, instanceID, state, anchor.Anchor())
	if err != nil {
		return AcceptedInstall{}, err
	}
	manifest, receipt, image, err := gate.initialProofs(ctx, state, anchor, observed, now)
	if err != nil {
		return AcceptedInstall{}, err
	}
	payload := manifest.Manifest()
	if !slices.Equal(payload.ControllerSlots, []string{"controller-a", "controller-b", "controller-c"}) ||
		!slices.Contains(payload.ControllerSlots, scope.Slot) || !slices.Contains(payload.ControllerSlots, payload.SeedSlot) {
		return AcceptedInstall{}, fmt.Errorf("%w: fresh installation requires the reviewed controller topology", ErrAdmission)
	}
	// A first install has no adopted generation: the manifest pins the config.
	if manifest.Manifest().ControllerConfigSHA256 != gate.LoadedControllerConfigSHA256 {
		return AcceptedInstall{}, fmt.Errorf("%w: loaded controller config differs from signed ledger manifest", ErrAdmission)
	}
	binary, err := gate.binaryChecker().VerifyCurrent(image)
	if err != nil {
		return AcceptedInstall{}, err
	}
	materials := expectedMaterials(manifest.Manifest(), scope.Slot)
	if len(materials) == 0 {
		return AcceptedInstall{}, fmt.Errorf("%w: no controller materials authorized", ErrAdmission)
	}
	receiptRecord := state.SeedReceiptRecord
	if state.Intent.Slot != manifest.Manifest().SeedSlot {
		receiptRecord = state.PeerReceiptRecord
	}
	manifestEnvelope, manifestErr := proofEnvelope(state.ManifestRecord.Bytes)
	receiptEnvelope, receiptErr := proofEnvelope(receiptRecord.Bytes)
	if manifestErr != nil || receiptErr != nil {
		return AcceptedInstall{}, ErrAdmission
	}
	marker := AcceptedInstall{
		SchemaVersion: 1, AnchorSHA256: anchor.Digest(), ManifestSHA256: state.ManifestRecord.SHA256,
		ReceiptSHA256: receiptRecord.SHA256, ImageReceiptSHA256: digest(manifest.Manifest().ReleaseImageReceiptWire),
		DeploymentID: scope.DeploymentID, Cell: scope.Cell, Slot: scope.Slot,
		SeedSlot:  manifest.Manifest().SeedSlot,
		ImageOCID: state.Intent.ImageOCID, InstanceOCID: instanceID,
		PrimaryVNICOCID: observed.PrimaryVNICOCID, PrimaryPrivateIP: observed.PrimaryPrivateIP,
		HeadAttempt: state.Head.Attempt, HeadGeneration: state.Head.Generation,
		ResultSHA256: state.ResultRecord.SHA256, BinarySHA256: binary.SHA256,
		MaterialSHA256: materials, AcceptedAt: now,
		ManagedMaterial: manifest.Manifest().ManagedMaterial,
	}
	if priorErr == nil {
		marker.AcceptedAt = prior.AcceptedAt
		if !sameInitialFormation(marker, prior) ||
			!coveredAt(anchor.IssuedAt(), anchor.ExpiresAt(), prior.AcceptedAt) ||
			!coveredAt(manifestEnvelope.IssuedAt, manifestEnvelope.ExpiresAt, prior.AcceptedAt) ||
			!coveredAt(image.IssuedAt(), image.ExpiresAt(), prior.AcceptedAt) ||
			!coveredAt(receiptEnvelope.IssuedAt, receiptEnvelope.ExpiresAt, prior.AcceptedAt) {
			return AcceptedInstall{}, fmt.Errorf("%w: initial formation recovery differs from verified current installation", ErrAdmission)
		}
	}
	launchStore := bakedStore{directory: BakedDirectory}
	if gate.trustStore != nil {
		launchStore = *gate.trustStore
	}
	launchPins, err := launchStore.measureInitialLaunchMaterial(manifest, gate.Roots, now)
	if err != nil {
		return AcceptedInstall{}, fmt.Errorf("measure current public host launch inputs: %w", err)
	}
	verifyCurrent := func(_ time.Time) error {
		if err := ctx.Err(); err != nil {
			return err
		}
		if err := gate.requireInitialJournalAbsent(); err != nil {
			return err
		}
		at, err := gate.checkedNow()
		if err != nil {
			return err
		}
		currentAnchor, err := bootstrap.VerifyBootstrapAnchor(anchorEnvelope, gate.Roots, gate.Expected,
			at, bootstrap.BootstrapAnchorTrustPolicy())
		if err != nil || currentAnchor.Digest() != anchor.Digest() {
			return fmt.Errorf("%w: current baked anchor or ledger grant expired: %v", ErrAdmission, err)
		}
		_, _, _, err = gate.initialProofs(ctx, state, currentAnchor, observed, at)
		if err != nil {
			return fmt.Errorf("%w: current manifest, image, or instance receipt expired: %v", ErrAdmission, err)
		}
		currentPins, err := launchStore.measureInitialLaunchMaterial(manifest, gate.Roots, at)
		if err != nil || !maps.Equal(launchPins, currentPins) {
			return fmt.Errorf("%w: current public host launch inputs changed or expired: %v", ErrAdmission, err)
		}
		return nil
	}
	if err := verifyCurrent(time.Time{}); err != nil {
		return AcceptedInstall{}, err
	}
	if pendingErr == nil {
		if pending.AcceptedAt.After(now) {
			return AcceptedInstall{}, ErrAdmission
		}
		rebuilt, err := AcceptedIdentityFromInitial(InitialAcceptedIdentityInputs{
			OperationID: entityid.Derive("accepted-install", manifest.Digest(), receiptRecord.SHA256),
			Manifest:    manifest, Receipt: receipt, Image: image, Observed: observed, Binary: binary,
			Broker: pending.Broker, Store: pending.Store, LaunchMaterialSHA256: launchPins,
			AcceptedAt: pending.AcceptedAt, VerifyCurrent: verifyCurrent,
		})
		if err != nil {
			return AcceptedInstall{}, err
		}
		if err := sameInitialExport(pending, rebuilt); err != nil {
			return AcceptedInstall{}, err
		}
		if err := verifyAcceptedStoreFiles(pending.Store); err != nil {
			return AcceptedInstall{}, err
		}
	}
	if err := gate.Material.PrepareInitial(ctx, manifest, receipt, materials, verifyCurrent); err != nil {
		return AcceptedInstall{}, fmt.Errorf("prepare current controller materials: %w", err)
	}
	if pendingErr == nil {
		if err := VerifyAcceptedLocalIdentity(pending, gate.ObserveIdentity); err != nil {
			return AcceptedInstall{}, err
		}
	}
	if err := gate.Credentials.VerifyInitialLiveCredentials(ctx, ManifestPins(materials), manifest); err != nil {
		return AcceptedInstall{}, fmt.Errorf("verify live controller credentials: %w", err)
	}
	acceptedAt, err := gate.checkedNow()
	if err != nil {
		return AcceptedInstall{}, err
	}
	if !coveredAt(anchor.IssuedAt(), anchor.ExpiresAt(), acceptedAt) ||
		!coveredAt(manifestEnvelope.IssuedAt, manifestEnvelope.ExpiresAt, acceptedAt) ||
		!coveredAt(image.IssuedAt(), image.ExpiresAt(), acceptedAt) ||
		!coveredAt(receiptEnvelope.IssuedAt, receiptEnvelope.ExpiresAt, acceptedAt) {
		return AcceptedInstall{}, fmt.Errorf("%w: signed proofs do not cover final acceptance time", ErrAdmission)
	}
	if err := ctx.Err(); err != nil {
		return AcceptedInstall{}, fmt.Errorf("%w: initial admission ended before acceptance: %w", ErrAdmission, err)
	}
	if priorErr != nil {
		marker.AcceptedAt = acceptedAt
	}

	if err := verifyCurrent(time.Time{}); err != nil {
		return AcceptedInstall{}, err
	}
	if state.Intent.Slot == manifest.Manifest().SeedSlot {
		if gate.InitialFounderFloor == nil {
			return AcceptedInstall{}, fmt.Errorf("%w: initial seed founder floor provisioner is absent", ErrAdmission)
		}
		if state.Intent.Mode != bootstrap.IntentModeExternalSeed || state.Head.Attempt != 1 ||
			state.Head.Generation != 1 {
			return AcceptedInstall{}, fmt.Errorf("%w: seed floor requires the first external-seed attempt", ErrAdmission)
		}
		if err := gate.InitialFounderFloor(ctx, marker, acceptedAt); err != nil {
			return AcceptedInstall{}, fmt.Errorf("%w: provision initial seed founder floor: %v", ErrAdmission, err)
		}
	} else if state.Intent.Mode == bootstrap.IntentModeManaged {
		if gate.InitialPeerFloor == nil {
			return AcceptedInstall{}, fmt.Errorf("%w: initial managed peer floor provisioner is absent", ErrAdmission)
		}
		if err := gate.InitialPeerFloor(ctx, marker, state, acceptedAt); err != nil {
			return AcceptedInstall{}, fmt.Errorf("%w: provision initial peer founder floor: %v", ErrAdmission, err)
		}
	}
	if err := verifyCurrent(time.Time{}); err != nil {
		return AcceptedInstall{}, err
	}
	finalAt, err := gate.checkedNow()
	if err != nil {
		return AcceptedInstall{}, err
	}
	if !coveredAt(anchor.IssuedAt(), anchor.ExpiresAt(), finalAt) ||
		!coveredAt(manifestEnvelope.IssuedAt, manifestEnvelope.ExpiresAt, finalAt) ||
		!coveredAt(image.IssuedAt(), image.ExpiresAt(), finalAt) ||
		!coveredAt(receiptEnvelope.IssuedAt, receiptEnvelope.ExpiresAt, finalAt) {
		return AcceptedInstall{}, fmt.Errorf("%w: signed proofs do not cover final marker publication time", ErrAdmission)
	}
	if err := ctx.Err(); err != nil {
		return AcceptedInstall{}, fmt.Errorf("%w: initial admission ended before marker publication: %w", ErrAdmission, err)
	}
	if err := verifyCurrent(finalAt); err != nil {
		return AcceptedInstall{}, err
	}
	broker, store, err := gate.InitialIdentity(manifest.Manifest())
	if err != nil {
		return AcceptedInstall{}, fmt.Errorf("prepare fresh installation identity: %w", err)
	}
	finalAt, err = gate.checkedNow()
	if err != nil {
		return AcceptedInstall{}, err
	}
	if priorErr != nil {
		marker.AcceptedAt = finalAt
	}
	acceptanceAt := finalAt
	if pendingErr == nil {
		if pending.AcceptedAt.After(finalAt) || !coveredAt(anchor.IssuedAt(), anchor.ExpiresAt(), pending.AcceptedAt) ||
			!coveredAt(manifestEnvelope.IssuedAt, manifestEnvelope.ExpiresAt, pending.AcceptedAt) ||
			!coveredAt(image.IssuedAt(), image.ExpiresAt(), pending.AcceptedAt) ||
			!coveredAt(receiptEnvelope.IssuedAt, receiptEnvelope.ExpiresAt, pending.AcceptedAt) {
			return AcceptedInstall{}, fmt.Errorf("%w: pending export acceptance is outside current proofs", ErrAdmission)
		}
		acceptanceAt = pending.AcceptedAt
	}
	accepted, err := AcceptedIdentityFromInitial(InitialAcceptedIdentityInputs{
		OperationID: entityid.Derive("accepted-install", manifest.Digest(), receiptRecord.SHA256),
		Manifest:    manifest, Receipt: receipt, Image: image, Observed: observed, Binary: binary,
		Broker: broker, Store: store, LaunchMaterialSHA256: launchPins,
		AcceptedAt: acceptanceAt, VerifyCurrent: verifyCurrent,
	})
	if err != nil {
		return AcceptedInstall{}, fmt.Errorf("normalize fresh accepted installation: %w", err)
	}
	if pendingErr == nil {
		if err := sameInitialExport(pending, accepted); err != nil {
			return AcceptedInstall{}, fmt.Errorf("%w: current installation differs from pending export: %w", ErrAdmission, err)
		}
	}
	if err := gate.requireInitialJournalAbsent(); err != nil {
		return AcceptedInstall{}, err
	}
	if err := gate.publishInitialFormation(marker); err != nil {
		return AcceptedInstall{}, err
	}
	if err := verifyCurrent(finalAt); err != nil {
		return AcceptedInstall{}, err
	}
	if err := gate.Markers.stageInitialExport(accepted, gate.ObserveIdentity); err != nil {
		return AcceptedInstall{}, fmt.Errorf("stage accepted-install export: %w", err)
	}
	if err := publishAcceptedInstall(ctx, ledger, scope, accepted); err != nil {
		return AcceptedInstall{}, err
	}
	if err := verifyCurrent(time.Time{}); err != nil {
		return AcceptedInstall{}, err
	}
	if err := gate.Markers.WriteNewIdentity(accepted, gate.ObserveIdentity); err != nil {
		return AcceptedInstall{}, fmt.Errorf("persist accepted-install marker: %w", err)
	}
	if err := gate.Markers.clearInitialExport(); err != nil {
		return AcceptedInstall{}, fmt.Errorf("clear completed initial export: %w", err)
	}
	return marker, nil
}

gate_restart.text:
func (gate Gate) AdmitRestart(ctx context.Context) (AcceptedIdentity, error) {
	if gate.Instances == nil {
		return AcceptedIdentity{}, fmt.Errorf("%w: authenticated OCI instance observer is absent", ErrAdmission)
	}
	if _, err := gate.checkedNow(); err != nil {
		return AcceptedIdentity{}, err
	}
	accepted, err := gate.AdmitRestartLocal(ctx)
	if err != nil {
		return AcceptedIdentity{}, err
	}
	observed, err := gate.Instances.ObserveInstance(ctx, accepted.InstanceOCID)
	if err != nil {
		return AcceptedIdentity{}, fmt.Errorf("observe accepted OCI instance: %w", err)
	}
	if observed.InstanceOCID != accepted.InstanceOCID || observed.ImageOCID != accepted.ImageOCID ||
		observed.PrimaryVNICOCID != accepted.PrimaryVNICOCID || observed.PrimaryPrivateIP != accepted.PrimaryPrivateIP ||
		!observed.PrimaryVNIC || observed.LifecycleState != "RUNNING" {
		return AcceptedIdentity{}, fmt.Errorf("%w: authenticated OCI physical identity differs from accepted installation", ErrAdmission)
	}
	if _, err := gate.checkedNow(); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := ctx.Err(); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := gate.checkAcceptedUnchanged(accepted); err != nil {
		return AcceptedIdentity{}, err
	}
	return accepted, nil
}

restart_local.text:
func (gate Gate) AdmitRestartLocal(ctx context.Context) (AcceptedIdentity, error) {
	return gate.admitRestartLocal(ctx, gate.verifyRestartBinary)
}

// AdmitIdentityRekeyCompletion admits only the read-only shared-completion probe.
// An owned transition may use its authenticated predecessor without admitting runtime.
func (gate Gate) AdmitIdentityRekeyCompletion(ctx context.Context) (AcceptedIdentity, error) {
	return gate.admitRestartLocal(ctx, func(accepted AcceptedIdentity, roots trust.Keyring) error {
		if err := gate.verifyRestartBinary(accepted, roots); err == nil {
			return nil
		}
		_, err := verifyRecoveryPredecessor("/proc/self/exe", gate.SelfUpdate, roots, accepted)
		return err
	})
}

func (gate Gate) admitRestartLocal(ctx context.Context, verifyBinary func(AcceptedIdentity, trust.Keyring) error) (AcceptedIdentity, error) {
	if gate.Descriptor == nil || gate.Material == nil || gate.Credentials == nil || gate.ObserveIdentity == nil ||
		gate.Markers.directory == "" || !markerDigestRE.MatchString(gate.LoadedControllerConfigSHA256) {
		return AcceptedIdentity{}, fmt.Errorf("%w: required local verifier is absent", ErrAdmission)
	}
	accepted, err := gate.Markers.ReadIdentity()
	if err != nil {
		return AcceptedIdentity{}, fmt.Errorf("read root-owned accepted installation: %w", err)
	}
	inputs, err := gate.acceptedTrustInputs(accepted)
	if err != nil {
		return AcceptedIdentity{}, err
	}
	if err := gate.checkRestartJournal(accepted, inputs); err != nil {
		return AcceptedIdentity{}, err
	}
	descriptor, err := gate.Descriptor.FetchDescriptor(ctx)
	if err != nil {
		return AcceptedIdentity{}, fmt.Errorf("read accepted local slot: %w", err)
	}
	instance, err := gate.Descriptor.FetchInstanceID(ctx)
	if err != nil {
		return AcceptedIdentity{}, fmt.Errorf("read accepted local instance ID: %w", err)
	}
	if descriptor.SchemaVersion != 1 || descriptor.Slot != accepted.Slot || instance != accepted.InstanceOCID {
		return AcceptedIdentity{}, fmt.Errorf("%w: IMDS slot or instance differs from accepted installation", ErrAdmission)
	}
	if err := verifyBinary(accepted, inputs.Roots.Historical); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := VerifyAcceptedLocalIdentity(accepted, gate.ObserveIdentity); err != nil {
		return AcceptedIdentity{}, fmt.Errorf("verify accepted broker/store identity: %w", err)
	}
	pins, err := gate.Material.RestartPins(accepted, inputs.Roots.Historical)
	if err != nil {
		return AcceptedIdentity{}, fmt.Errorf("read accepted material generation: %w", err)
	}
	if err := gate.restartConfig(&pins, accepted); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := gate.Material.VerifyRestart(ctx, accepted, pins); err != nil {
		return AcceptedIdentity{}, fmt.Errorf("verify installed controller material: %w", err)
	}
	if err := gate.Credentials.VerifyLiveCredentials(ctx, pins, accepted); err != nil {
		return AcceptedIdentity{}, fmt.Errorf("verify live controller credentials: %w", err)
	}
	if err := ctx.Err(); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := gate.checkAcceptedUnchanged(accepted); err != nil {
		return AcceptedIdentity{}, err
	}
	if err := verifyBinary(accepted, inputs.Roots.Historical); err != nil {
		return AcceptedIdentity{}, err
	}
	return accepted, nil
}

func (gate Gate) acceptedTrustInputs(accepted AcceptedIdentity) (TrustInputs, error) {
	if gate.trustStore != nil {
		return gate.trustStore.loadTrustInputs(accepted)
	}
	return LoadTrustInputs(accepted)
}

func (gate Gate) checkRestartJournal(accepted AcceptedIdentity, inputs TrustInputs) error {
	_, err := gate.Markers.verifiedIdentityRekey(accepted, inputs)
	if errors.Is(err, os.ErrNotExist) {
		return nil
	}
	return err
}

func (gate Gate) checkAcceptedUnchanged(accepted AcceptedIdentity) error {
	current, err := gate.Markers.ReadIdentity()
	if err != nil {
		return err
	}
	before, err := EncodeAcceptedIdentity(accepted)
	if err != nil {
		return err
	}
	after, err := EncodeAcceptedIdentity(current)
	if err != nil || !bytes.Equal(before, after) {
		return fmt.Errorf("%w: root-owned accepted installation changed during admission", ErrAdmission)
	}
	inputs, err := gate.acceptedTrustInputs(current)
	if err != nil {
		return err
	}
	return gate.checkRestartJournal(current, inputs)
}

marker_read.text:
func (store MarkerStore) ReadIdentity() (AcceptedIdentity, error) {
	dir, err := store.openDirectory()
	if err != nil {
		return AcceptedIdentity{}, err
	}
	defer unix.Close(dir)
	wire, err := store.readIdentityBytes(dir, markerName)
	if err != nil {
		return AcceptedIdentity{}, err
	}
	return DecodeAcceptedIdentity(wire)
}

func (store MarkerStore) readIdentityBytes(dir int, name string) ([]byte, error) {
	fd, err := unix.Openat(dir, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), name)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != store.ownerUID || store.ownerUID == 0 && stat.Gid != 0 || stat.Mode&0o7777 != 0o644 ||
		stat.Nlink != 1 || stat.Size <= 0 || stat.Size > MaxAcceptedIdentityBytes {
		return nil, ErrAcceptedIdentity
	}
	wire, err := io.ReadAll(io.LimitReader(file, MaxAcceptedIdentityBytes+1))
	if err != nil || len(wire) == 0 || len(wire) > MaxAcceptedIdentityBytes {
		return nil, ErrAcceptedIdentity
	}
	return wire, nil
}

marker_publish.text:
func (store MarkerStore) WriteNewIdentity(identity AcceptedIdentity, observe IdentityObservation) error {
	return store.publishIdentity(identity.Clone(), "", observe)
}

// ReplaceIdentity never interprets the predecessor as an identity document.
func (store MarkerStore) ReplaceIdentity(verified identityrekey.VerifiedIdentityCheckpoint, slot string,
	acceptedAt time.Time, observe IdentityObservation,
) error {
	identity, err := AcceptedIdentityFromCheckpoint(verified, slot, acceptedAt)
	if err != nil {
		return err
	}
	for _, binding := range verified.Checkpoint().Slots {
		if binding.Slot == slot {
			return store.publishIdentity(identity, binding.PreviousAcceptanceSHA256, observe)
		}
	}
	return ErrAcceptedIdentity
}

func (store MarkerStore) publishIdentity(identity AcceptedIdentity, predecessor string, observe IdentityObservation) error {
	return store.publishIdentityAt(identity, predecessor, observe, markerName)
}

func (store MarkerStore) publishIdentityAt(identity AcceptedIdentity, predecessor string, observe IdentityObservation, name string) error {
	wire, err := EncodeAcceptedIdentity(identity)
	if err != nil {
		return err
	}
	if err := VerifyAcceptedLocalIdentity(identity, observe); err != nil {
		return err
	}
	dir, err := store.openDirectory()
	if err != nil {
		return err
	}
	defer unix.Close(dir)
	lock, err := unix.Openat(dir, ".accepted-identity.lock", unix.O_RDWR|unix.O_CREAT|unix.O_EXCL|unix.O_NOFOLLOW|unix.O_NONBLOCK|unix.O_CLOEXEC, 0o644)
	created := err == nil
	if errors.Is(err, unix.EEXIST) {
		lock, err = unix.Openat(dir, ".accepted-identity.lock", unix.O_RDWR|unix.O_NOFOLLOW|unix.O_NONBLOCK|unix.O_CLOEXEC, 0)
	}
	if err != nil {
		return err
	}
	defer unix.Close(lock)
	var stat unix.Stat_t
	if err := unix.Fstat(lock, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Uid != store.ownerUID || store.ownerUID == 0 && stat.Gid != 0 || stat.Nlink != 1 {
		return ErrAcceptedIdentity
	}
	if created {
		if err := unix.Fchmod(lock, 0o644); err != nil {
			return err
		}
	} else if stat.Mode&0o7777 != 0o644 {
		return ErrAcceptedIdentity
	}
	if err := unix.Flock(lock, unix.LOCK_EX); err != nil {
		return err
	}
	defer unix.Flock(lock, unix.LOCK_UN)
	if predecessor != "" {
		old, err := store.readIdentityBytes(dir, markerName)
		if err != nil {
			return err
		}
		if digest(old) != predecessor {
			return ErrAcceptancePredecessor
		}
	}
	var nonce [12]byte
	if _, err := rand.Read(nonce[:]); err != nil {
		return err
	}
	temporary := ".accepted-install." + hex.EncodeToString(nonce[:])
	fd, err := unix.Openat(dir, temporary, unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0o644)
	if err != nil {
		return err
	}
	defer unix.Unlinkat(dir, temporary, 0)
	file := os.NewFile(uintptr(fd), temporary)
	defer file.Close()
	if err := unix.Fchmod(fd, 0o644); err != nil {
		return err
	}
	if err := unix.Fstat(fd, &stat); err != nil || stat.Uid != store.ownerUID || store.ownerUID == 0 && stat.Gid != 0 ||
		stat.Mode&unix.S_IFMT != unix.S_IFREG || stat.Nlink != 1 {
		return ErrAcceptedIdentity
	}
	if count, err := file.Write(wire); err != nil {
		return err
	} else if count != len(wire) {
		return io.ErrShortWrite
	}
	if err := file.Sync(); err != nil {
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := VerifyAcceptedLocalIdentity(identity, observe); err != nil {
		return err
	}
	if predecessor == "" {
		err = unix.Renameat2(dir, temporary, dir, name, unix.RENAME_NOREPLACE)
	} else {
		old, readErr := store.readIdentityBytes(dir, markerName)
		if readErr != nil {
			return readErr
		}
		if digest(old) != predecessor {
			return ErrAcceptancePredecessor
		}
		err = unix.Renameat(dir, temporary, dir, markerName)
	}
	if err != nil {
		return err
	}
	return unix.Fsync(dir)
}

continuation.text:
func (checker *FounderPeerContinuation) Initialize(ctx context.Context, marker AcceptedInstall,
	state bootstrap.SlotState, now time.Time,
) error {
	if checker == nil || checker.reader == nil || checker.floor == nil ||
		checker.serviceUID == 0 || checker.serviceGID == 0 || checker.now == nil ||
		now.IsZero() || now.Location() != time.UTC {
		return ErrFounderPeerContinuation
	}
	started := time.Now()
	selected, err := checker.reader.readCurrentPeerInitial(ctx, now)
	if err != nil {
		return fmt.Errorf("%w: read current selected founder proof: %v", ErrFounderPeerContinuation, err)
	}
	if err := checker.checkBindings(marker, state, selected, now); err != nil {
		return err
	}
	if err := prepareFounderFloorOwner(checker.floor, checker.serviceUID, checker.serviceGID); err != nil {
		return fmt.Errorf("%w: prepare peer selection floor: %v", ErrFounderPeerContinuation, err)
	}
	if err := checker.floor.InitializePeerForService(selected.SelectionGeneration, selected.SelectionSHA256,
		checker.serviceGID); err != nil {
		return fmt.Errorf("%w: publish peer selection floor: %v", ErrFounderPeerContinuation, err)
	}
	if err := checker.reader.confirmCurrentPeerSelection(ctx, selected,
		func() time.Time { return checker.now().Round(0).UTC().Add(time.Since(started)) }); err != nil {
		return fmt.Errorf("%w: selector changed after floor publication: %v", ErrFounderPeerContinuation, err)
	}
	return nil
}

func (checker *FounderPeerContinuation) checkBindings(marker AcceptedInstall, state bootstrap.SlotState,
	selected currentFounderPeerSelection, now time.Time,
) error {
	if marker.validate() != nil || marker.Slot == marker.SeedSlot ||
		checker.reader.accepted.Slot != marker.Slot ||
		checker.reader.accepted.SeedSlot != marker.SeedSlot ||
		checker.reader.accepted.AnchorSHA256 != marker.AnchorSHA256 ||
		checker.reader.accepted.ManifestSHA256 != marker.ManifestSHA256 ||
		!selected.Anchor.IsVerified() || selected.Plan == nil || !selected.Plan.IsVerified() ||
		selected.Anchor.Digest() != marker.AnchorSHA256 ||
		selected.Plan.Digest() != state.Intent.FounderPlanSHA256 ||
		state.Intent.SchemaVersion != 1 || state.Intent.Mode != bootstrap.IntentModeManaged ||
		state.Head.SchemaVersion != 1 || state.Head.ResultDigest != marker.ResultSHA256 ||
		state.Result == nil || state.ResultRecord == nil || state.Candidate == nil || state.CandidateRecord == nil ||
		state.ManifestRecord == nil || state.PeerReceiptRecord == nil ||
		state.ResultRecord.SHA256 != marker.ResultSHA256 ||
		state.PeerReceiptRecord.SHA256 != marker.ReceiptSHA256 ||
		state.ManifestRecord.SHA256 != marker.ManifestSHA256 ||
		state.Head.CandidateDigest != state.CandidateRecord.SHA256 ||
		state.Head.ResultDigest != state.ResultRecord.SHA256 ||
		state.Candidate.InstanceOCID != marker.InstanceOCID || state.Result.InstanceOCID != marker.InstanceOCID ||
		state.Result.Mode != bootstrap.IntentModeManaged ||
		state.Intent.DeploymentID != marker.DeploymentID || state.Intent.Cell != marker.Cell ||
		state.Intent.Slot != marker.Slot || state.Intent.ManifestDigest != marker.ManifestSHA256 ||
		state.Result.DeploymentID != marker.DeploymentID || state.Result.Cell != marker.Cell ||
		state.Result.Slot != marker.Slot || state.Candidate.DeploymentID != marker.DeploymentID ||
		state.Candidate.Cell != marker.Cell || state.Candidate.Slot != marker.Slot ||
		state.Intent.ImageOCID != marker.ImageOCID ||
		state.Head.Attempt != marker.HeadAttempt || state.Head.Generation != marker.HeadGeneration ||
		state.Candidate.IntentDigest != state.IntentRecord.SHA256 ||
		state.Result.IntentDigest != state.IntentRecord.SHA256 ||
		state.Candidate.FounderPlanSHA256 != state.Intent.FounderPlanSHA256 ||
		state.Candidate.PeerRowDigest != state.Intent.PeerRowDigest ||
		state.Candidate.ManifestDigest != state.Intent.ManifestDigest {
		return ErrFounderPeerContinuation
	}
	if selected.Plan.SeedSlot() != marker.SeedSlot ||
		selected.SelectionGeneration == 0 || !now.Before(selected.SelectionExpiresAt) ||
		!selected.Plan.StoredCompletionBeforeLaunchDeadline(state.ResultRecord.LastModified,
			state.HeadRecord.LastModified) ||
		digestWire(selected.ManifestWires[marker.Slot]) != marker.ManifestSHA256 {
		return ErrFounderPeerContinuation
	}
	row, ok := selected.Plan.PeerRow(marker.Slot)
	if ok {
		rowDigest, err := bootstrap.FounderPeerRowDigest(row)
		if err == nil && rowDigest == state.Intent.PeerRowDigest &&
			row.ManifestSHA256 == marker.ManifestSHA256 && row.ImageOCID == marker.ImageOCID &&
			row.CompartmentOCID == state.Intent.CompartmentOCID {
			return nil
		}
	}

