func testFounderFloor(t *testing.T) *FounderSelectionFloorStore {
	t.Helper()
	directory := filepath.Join(t.TempDir(), "controller")
	if err := os.Mkdir(directory, 0o700); err != nil {
		t.Fatal(err)
	}
	return &FounderSelectionFloorStore{directory: directory, ownerUID: uint32(os.Geteuid()), allowUnsafeAncestors: true}
}

func testFounderServiceIdentity() (uint32, uint32) {
	if os.Geteuid() == 0 {
		return 65534, 65534
	}
	return uint32(os.Geteuid()), uint32(os.Getegid())
}

floor_initial.text:
func (store *FounderSelectionFloorStore) Initialize(generation uint64, selectionSHA256 string) error {
	if generation == 0 || !validFounderDigest(selectionSHA256) {
		return ErrFounderSelectionFloor
	}
	dir, err := store.openDirectory()
	if err != nil {
		return err
	}
	defer unix.Close(dir)
	if err := store.withLock(dir, func() error {
		return store.writeNew(dir, founderSelectionFloor{SchemaVersion: 1,
			Generation: generation, SelectionSHA256: selectionSHA256}, true, nil)
	}); err != nil {
		return err
	}
	return nil
}

// InitializeForService is the initial root admission's one-time publication.
// It writes the file with the service directory's exact owner before fsyncing
// either the file or directory, so a crash cannot expose a durable root-owned
// floor that the unprivileged seed cannot replay.
func (store *FounderSelectionFloorStore) InitializeForService(generation uint64, selectionSHA256 string,
	serviceGID uint32,
) error {
	if store == nil || store.ownerUID == 0 || serviceGID == 0 || generation != 1 ||
		!validFounderDigest(selectionSHA256) {
		return ErrFounderSelectionFloor
	}
	return store.initializeForService(generation, selectionSHA256, serviceGID, false)
}

// InitializePeerForService records the root-verified selector seen at first
// managed-peer admission. A prior floor can replay an interrupted install,
// but it can never move backward or change digest at the same generation.
func (store *FounderSelectionFloorStore) InitializePeerForService(generation uint64, selectionSHA256 string,
	serviceGID uint32,
) error {
	if store == nil || store.ownerUID == 0 || serviceGID == 0 || generation == 0 ||
		!validFounderDigest(selectionSHA256) {
		return ErrFounderSelectionFloor
	}
	return store.initializeForService(generation, selectionSHA256, serviceGID, true)
}

func (store *FounderSelectionFloorStore) initializeForService(generation uint64, selectionSHA256 string,
	serviceGID uint32, allowReplay bool,
) error {
	dir, err := store.openDirectory()
	if err != nil {
		return err
	}
	defer unix.Close(dir)
	var stat unix.Stat_t
	if err := unix.Fstat(dir, &stat); err != nil || stat.Gid != serviceGID {
		return ErrFounderSelectionFloor
	}
	owner := struct{ uid, gid uint32 }{store.ownerUID, serviceGID}
	return store.withLock(dir, func() error {
		if allowReplay {
			current, readErr := store.read(dir)
			if readErr == nil {
				if generation < current.Generation ||
					generation == current.Generation && selectionSHA256 != current.SelectionSHA256 {
					return ErrFounderSelectionFloor
				}
				if generation == current.Generation {
					return unix.Fsync(dir)
				}
				return store.writeNew(dir, founderSelectionFloor{SchemaVersion: 1,
					Generation: generation, SelectionSHA256: selectionSHA256}, false, &owner)
			}
			if !errors.Is(readErr, os.ErrNotExist) {
				return readErr
			}
		}
		return store.writeNew(dir, founderSelectionFloor{SchemaVersion: 1,
			Generation: generation, SelectionSHA256: selectionSHA256}, true, &owner)
	})
}

floor_inspect.text:
func (store *FounderSelectionFloorStore) Check(generation uint64, selectionSHA256 string) error {
	return store.inspect(generation, selectionSHA256, false)
}

func (store *FounderSelectionFloorStore) Observe(generation uint64, selectionSHA256 string) error {
	return store.inspect(generation, selectionSHA256, true)
}

func (store *FounderSelectionFloorStore) inspect(generation uint64, selectionSHA256 string, advance bool) error {
	if generation == 0 || !validFounderDigest(selectionSHA256) {
		return ErrFounderSelectionFloor
	}
	dir, err := store.openDirectory()
	if err != nil {
		return err
	}
	defer unix.Close(dir)
	return store.withLock(dir, func() error {
		current, err := store.read(dir)
		if err != nil {
			return err
		}
		if generation < current.Generation || generation == current.Generation && selectionSHA256 != current.SelectionSHA256 {
			return ErrFounderSelectionFloor
		}
		if advance && generation > current.Generation {
			return store.writeNew(dir, founderSelectionFloor{SchemaVersion: 1,
				Generation: generation, SelectionSHA256: selectionSHA256}, false, nil)
		}
		if advance {
			// A prior Renameat may have succeeded while its directory fsync
			// failed. Never treat a visible equal-generation floor as durable
			// until a directory fsync succeeds before this effect.
			return unix.Fsync(dir)
		}
		return nil
	})

floor_directory.text:
func (store *FounderSelectionFloorStore) openDirectory() (int, error) {
	if store == nil || !filepath.IsAbs(store.directory) || filepath.Clean(store.directory) != store.directory {
		return -1, ErrFounderSelectionFloor
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return -1, err
	}
	for component := range strings.SplitSeq(strings.TrimPrefix(store.directory, "/"), "/") {
		if component == "" || component == "." || component == ".." {
			unix.Close(fd)
			return -1, ErrFounderSelectionFloor
		}
		next, err := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
		unix.Close(fd)
		if err != nil {
			return -1, err
		}
		fd = next
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil ||
			!store.allowUnsafeAncestors && stat.Uid != 0 && stat.Uid != store.ownerUID ||
			!store.allowUnsafeAncestors && stat.Mode&0o022 != 0 {
			unix.Close(fd)
			return -1, ErrFounderSelectionFloor
		}
	}
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Uid != store.ownerUID || stat.Mode&0o777 != 0o700 {
		unix.Close(fd)
		return -1, ErrFounderSelectionFloor
	}
	return fd, nil
}

func (store *FounderSelectionFloorStore) withLock(dir int, work func() error) error {
	fd, err := unix.Openat(dir, founderSelectionLockName, unix.O_RDWR|unix.O_CREAT|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0o600)
	if err != nil {
		return err
	}
	defer unix.Close(fd)
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Mode&0o777 != 0o600 || stat.Uid != store.ownerUID || stat.Nlink != 1 {
		return ErrFounderSelectionFloor
	}
	if err := unix.Flock(fd, unix.LOCK_EX); err != nil {
		return err
	}
	defer unix.Flock(fd, unix.LOCK_UN)
	return work()

floor_readwrite.text:
func (store *FounderSelectionFloorStore) read(dir int) (founderSelectionFloor, error) {
	fd, err := unix.Openat(dir, founderSelectionFloorName, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	if err != nil {
		return founderSelectionFloor{}, fmt.Errorf("%w: %w", ErrFounderSelectionFloor, err)
	}
	file := os.NewFile(uintptr(fd), founderSelectionFloorName)
	defer file.Close()
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Mode&0o777 != 0o600 || stat.Uid != store.ownerUID || stat.Nlink != 1 ||
		stat.Size < 1 || stat.Size > founderSelectionFloorMax {
		return founderSelectionFloor{}, ErrFounderSelectionFloor
	}
	wire, err := io.ReadAll(io.LimitReader(file, founderSelectionFloorMax+1))
	if err != nil || len(wire) != int(stat.Size) {
		return founderSelectionFloor{}, ErrFounderSelectionFloor
	}
	var floor founderSelectionFloor
	if protocol.DecodeStrict(wire, &floor, founderSelectionFloorMax) != nil || floor.SchemaVersion != 1 ||
		floor.Generation == 0 || !validFounderDigest(floor.SelectionSHA256) {
		return founderSelectionFloor{}, ErrFounderSelectionFloor
	}
	canonical, err := protocol.EncodeJSON(floor)
	if err != nil || !bytes.Equal(canonical, wire) {
		return founderSelectionFloor{}, ErrFounderSelectionFloor
	}
	return floor, nil
}

func (store *FounderSelectionFloorStore) writeNew(dir int, floor founderSelectionFloor, initialize bool,
	owner *struct{ uid, gid uint32 },
) error {
	wire, err := encodeFounderSelectionFloor(floor.Generation, floor.SelectionSHA256)
	if err != nil || floor.SchemaVersion != 1 {
		return ErrFounderSelectionFloor
	}
	if initialize {
		var nonce [12]byte
		if _, err := rand.Read(nonce[:]); err != nil {
			return err
		}
		temporary := ".founder-selection-initial." + hex.EncodeToString(nonce[:])
		fd, err := unix.Openat(dir, temporary,
			unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0o600)
		if err != nil {
			return err
		}
		remove := true
		defer func() {
			if remove {
				_ = unix.Unlinkat(dir, temporary, 0)
			}
		}()
		file := os.NewFile(uintptr(fd), temporary)
		if owner != nil {
			var stat unix.Stat_t
			if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
				stat.Mode&0o777 != 0o600 || stat.Nlink != 1 {
				_ = file.Close()
				return ErrFounderSelectionFloor
			}
			if stat.Uid != owner.uid || stat.Gid != owner.gid {
				if err := unix.Fchown(fd, int(owner.uid), int(owner.gid)); err != nil {
					_ = file.Close()
					return err
				}
			}
		}
		written, writeErr := file.Write(wire)
		if written != len(wire) && writeErr == nil {
			writeErr = io.ErrShortWrite
		}
		syncErr := file.Sync()
		closeErr := file.Close()
		if err := errors.Join(writeErr, syncErr, closeErr); err != nil {
			return err
		}
		if err := unix.Renameat2(dir, temporary, dir, founderSelectionFloorName, unix.RENAME_NOREPLACE); err != nil {
			return err
		}
		remove = false
		return unix.Fsync(dir)
	}
	var nonce [12]byte
	if _, err := rand.Read(nonce[:]); err != nil {
		return err
	}
	temporary := ".founder-selection-floor." + hex.EncodeToString(nonce[:])
	fd, err := unix.Openat(dir, temporary, unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0o600)
	if err != nil {
		return err
	}
	remove := true
	defer func() {
		if remove {
			_ = unix.Unlinkat(dir, temporary, 0)
		}
	}()
	file := os.NewFile(uintptr(fd), temporary)
	if owner != nil {
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
			stat.Mode&0o777 != 0o600 || stat.Nlink != 1 {
			_ = file.Close()
			return ErrFounderSelectionFloor
		}
		if stat.Uid != owner.uid || stat.Gid != owner.gid {
			if err := unix.Fchown(fd, int(owner.uid), int(owner.gid)); err != nil {
				_ = file.Close()
				return err
			}
		}
	}
	written, writeErr := file.Write(wire)
	if written != len(wire) && writeErr == nil {
		writeErr = io.ErrShortWrite
	}
	syncErr := file.Sync()
	closeErr := file.Close()
	if err := errors.Join(writeErr, syncErr, closeErr); err != nil {
		return err
	}
	if err := unix.Renameat(dir, temporary, dir, founderSelectionFloorName); err != nil {
		return err
	}
	remove = false
	return unix.Fsync(dir)
}

completion_fact.text:
func newFounderPeersCompleteFact(accepted AcceptedInstall) founderPeersCompleteFact {
	return founderPeersCompleteFact{SchemaVersion: 1, DeploymentID: accepted.DeploymentID,
		Cell: accepted.Cell, SeedSlot: accepted.SeedSlot, InstanceOCID: accepted.InstanceOCID,
		AnchorSHA256: accepted.AnchorSHA256, ManifestSHA256: accepted.ManifestSHA256}
}

// PeersComplete reports whether a canonical completion fact for this exact
// accepted seed install is durable. Any absent, malformed, foreign, or
// mismatched fact reads as incomplete so the caller repeats the ledger read.
func (store *FounderSelectionFloorStore) PeersComplete(accepted AcceptedInstall) bool {
	if accepted.Slot != accepted.SeedSlot {
		return false
	}
	dir, err := store.openDirectory()
	if err != nil {
		return false
	}
	defer unix.Close(dir)
	complete := false
	_ = store.withLock(dir, func() error {
		fd, err := unix.Openat(dir, founderPeersCompleteName, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
		if err != nil {
			return err
		}
		file := os.NewFile(uintptr(fd), founderPeersCompleteName)
		defer file.Close()
		var stat unix.Stat_t
		if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
			stat.Mode&0o777 != 0o600 || stat.Uid != store.ownerUID || stat.Nlink != 1 ||
			stat.Size < 1 || stat.Size > founderPeersCompleteMax {
			return ErrFounderSelectionFloor
		}
		wire, err := io.ReadAll(io.LimitReader(file, founderPeersCompleteMax+1))
		if err != nil || len(wire) != int(stat.Size) {
			return ErrFounderSelectionFloor
		}
		var fact founderPeersCompleteFact
		if protocol.DecodeStrict(wire, &fact, founderPeersCompleteMax) != nil {
			return ErrFounderSelectionFloor
		}
		canonical, err := protocol.EncodeJSON(fact)
		if err != nil || !bytes.Equal(canonical, wire) {
			return ErrFounderSelectionFloor
		}
		complete = fact == newFounderPeersCompleteFact(accepted)
		return nil
	})
	return complete
}

// MarkPeersComplete durably records completion after a verified result for
// every planned peer. It replaces any older fact atomically.
func (store *FounderSelectionFloorStore) MarkPeersComplete(accepted AcceptedInstall) error {
	if accepted.validate() != nil || accepted.Slot != accepted.SeedSlot {
		return ErrFounderRuntime
	}
	wire, err := protocol.EncodeJSON(newFounderPeersCompleteFact(accepted))
	if err != nil || len(wire) > founderPeersCompleteMax {
		return ErrFounderSelectionFloor
	}
	dir, err := store.openDirectory()
	if err != nil {
		return err
	}
	defer unix.Close(dir)
	return store.withLock(dir, func() error {
		var nonce [12]byte
		if _, err := rand.Read(nonce[:]); err != nil {
			return err
		}
		temporary := ".founder-peers-complete." + hex.EncodeToString(nonce[:])
		fd, err := unix.Openat(dir, temporary,
			unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0o600)
		if err != nil {
			return err
		}
		remove := true
		defer func() {
			if remove {
				_ = unix.Unlinkat(dir, temporary, 0)
			}
		}()
		file := os.NewFile(uintptr(fd), temporary)
		written, writeErr := file.Write(wire)
		if written != len(wire) && writeErr == nil {
			writeErr = io.ErrShortWrite
		}
		syncErr := file.Sync()
		closeErr := file.Close()
		if err := errors.Join(writeErr, syncErr, closeErr); err != nil {
			return err
		}
		if err := unix.Renameat(dir, temporary, dir, founderPeersCompleteName); err != nil {
			return err
		}
		remove = false
		return unix.Fsync(dir)
	})
}

ledger_read.text:
func (ledger *Ledger) read(ctx context.Context, scope BootstrapScope, attempt uint64, kind ledgerRecordKind) (StoredRecord, error) {
	if err := validateLedgerScope(scope); err != nil {
		return StoredRecord{}, err
	}
	if attempt == 0 {
		return StoredRecord{}, errors.New("bootstrap ledger attempt must be positive")
	}
	return ledger.readObject(ctx, ledger.config.Bucket, ledger.objectName(scope, attempt, kind))
}

func (ledger *Ledger) readExistingExact(
	ctx context.Context,
	scope BootstrapScope,
	attempt uint64,
	kind ledgerRecordKind,
	body []byte,
) (StoredRecord, bool, error) {
	record, err := ledger.read(ctx, scope, attempt, kind)
	if errors.Is(err, ErrRecordMissing) {
		return StoredRecord{}, false, nil
	}
	if err != nil {
		return StoredRecord{}, false, err
	}
	if !bytes.Equal(record.Bytes, body) {
		return StoredRecord{}, true, ErrImmutableConflict
	}
	return record, true, nil
}

func (ledger *Ledger) readObject(ctx context.Context, bucket, objectName string) (StoredRecord, error) {
	return ledger.readObjectLimit(ctx, bucket, objectName, ledger.maxRecord)
}

func (ledger *Ledger) readObjectLimit(ctx context.Context, bucket, objectName string, maximum int) (StoredRecord, error) {
	if ledger.config.DerivedStartup != nil {
		authority := *ledger.config.DerivedStartup
		if ledger.now().Before(authority.ExpiresAt()) {
			if err := authority.VerifyCurrent(ctx, ledger.now()); err != nil {
				return StoredRecord{}, err
			}
		} else if _, err := authority.historical(ctx, authority.Wire()); err != nil {
			return StoredRecord{}, err
		}
	}
	response, err := ledger.client.GetObject(ociclient.RequestContext(ctx), objectstorage.GetObjectRequest{
		NamespaceName: new(ledger.config.Namespace),
		BucketName:    new(bucket),
		ObjectName:    new(objectName),
	})
	if err != nil {
		if serviceErr, ok := errors.AsType[objectStorageServiceError](err); ok && serviceErr.GetHTTPStatusCode() == http.StatusNotFound {
			return StoredRecord{}, ErrRecordMissing
		}
		return StoredRecord{}, fmt.Errorf("read exact bootstrap object: %w", err)
	}
	if response.Content == nil {
		return StoredRecord{}, errors.New("bootstrap object response has no body")
	}
	if response.ContentLength == nil || *response.ContentLength < 1 || *response.ContentLength > int64(maximum) {
		response.Content.Close()
		return StoredRecord{}, errors.New("bootstrap object has missing or invalid content length")
	}
	body, err := io.ReadAll(io.LimitReader(response.Content, int64(maximum)+1))
	closeErr := response.Content.Close()
	if err := errors.Join(err, closeErr); err != nil {
		return StoredRecord{}, fmt.Errorf("read bootstrap object body: %w", err)
	}
	if len(body) != int(*response.ContentLength) || len(body) > maximum {
		return StoredRecord{}, errors.New("bootstrap object body length does not match its metadata")
	}
	if response.ETag == nil || strings.TrimSpace(*response.ETag) == "" || response.LastModified == nil {
		return StoredRecord{}, errors.New("bootstrap object is missing ETag or Last-Modified metadata")
	}
	if response.RawResponse == nil {
		return StoredRecord{}, errors.New("bootstrap object response is missing server headers")
	}
	serverDate, err := http.ParseTime(response.RawResponse.Header.Get("Date"))
	if err != nil {
		return StoredRecord{}, errors.New("bootstrap object response has a missing or invalid server Date")
	}
	lastModified := response.LastModified.Time.UTC()
	serverDate = serverDate.UTC()
	if lastModified.IsZero() || serverDate.Before(lastModified) {
		return StoredRecord{}, errors.New("bootstrap object server timestamps are inconsistent")
	}
	digest := sha256.Sum256(body)
	return StoredRecord{
		Bytes: body, SHA256: hex.EncodeToString(digest[:]), ETag: *response.ETag,
		LastModified: lastModified, ServerDate: serverDate,
	}, nil
}

ledger_slot.text:
func (ledger *Ledger) ReadSlot(ctx context.Context, scope BootstrapScope) (SlotState, error) {
	state, err := ledger.readSlot(ctx, scope, false)
	if err == nil {
		return state, nil
	}
	// Managed peer records can be valid historical evidence whose
	// signed interval or exact proof timing is no longer current. Preserve that
	// distinction for read-only callers while keeping malformed or mismatched
	// records as hard errors.
	quarantined, recoveryErr := ledger.readSlotWithRecovery(ctx, scope, false, true)
	if recoveryErr == nil && quarantined.Intent.Mode == IntentModeManaged &&
		quarantined.quarantined {
		return SlotState{}, fmt.Errorf("%w: slot %q", ErrManagedPeerProofQuarantined, scope.Slot)
	}
	return SlotState{}, err
}

prepare_floor_owner.text:
func prepareFounderFloorOwner(floor *FounderSelectionFloorStore, uid, gid uint32) error {
	dir, err := floor.openDirectory()
	if err != nil {
		return err
	}
	defer unix.Close(dir)
	fd, err := unix.Openat(dir, founderSelectionLockName, unix.O_RDWR|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	created := false
	if errors.Is(err, unix.ENOENT) {
		fd, err = unix.Openat(dir, founderSelectionLockName,
			unix.O_RDWR|unix.O_CREAT|unix.O_EXCL|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0o600)
		created = err == nil
	}
	if err != nil {
		return err
	}
	defer unix.Close(fd)
	var stat unix.Stat_t
	if err := unix.Fstat(fd, &stat); err != nil || stat.Mode&unix.S_IFMT != unix.S_IFREG ||
		stat.Mode&0o777 != 0o600 || stat.Nlink != 1 || !created &&
		(stat.Uid != uid || stat.Gid != gid) &&
		(os.Geteuid() != 0 || stat.Uid != 0 || stat.Gid != 0 || stat.Size != 0) {
		return ErrFounderProvision
	}
	if stat.Uid == uid && stat.Gid == gid {
		if err := unix.Fsync(fd); err != nil {
			return err
		}
		return unix.Fsync(dir)
	}
	if err := unix.Fchown(fd, int(uid), int(gid)); err != nil {
		return err
	}
	if err := unix.Fsync(fd); err != nil {
		return err
	}
	return unix.Fsync(dir)
}
